"""
    get rid of possible spaces around farm location string
    """
def preprocess_location(location: Any) -> object {
    locations = location.split(',');
    res = "";
    for location in locations {
        res = res + location.strip() + ",";
    }
    res = res[:-1];
    return res;
}

"""zfill a string by padding 0s to the left of the string till it is the link
    specified by l.
    """
def _zfill(v: Any, l: Any = 5) -> object {
    return (("0" * (l - len(v))) + v);
}

"""
    Return sequence accuracy score. Match is counted only when the two sequences are equal.

    :param y_true: true labels
    :param y_pred: predicted labels

    :return: sequence accuracy as a fraction of the sample (1 is prefect, 0 is all incorrect)
    """
def sequence_accuracy_score(y_true: Any, y_pred: Any) -> object {
    total = len(y_true);
    matches = sum(
        1
        for (yseq_true, yseq_pred) in zip(y_true, y_pred)
        if (`list(yseq_true) == `list(yseq_pred))
    );
    return (matches / total);
}

